// Room "P1 west bedroom" (interior designer's part): two beds on the west wall (heads against the solid wall at x18,
// z14 and z20), a chest dresser on the north wall, a spruce-fence table with a top slab and a standing lantern in the
// middle, a brown rug on the floor and a barrel dresser at the south corner. Inner air x19..21, y6..8, z14..20.
// Everything is drawn as text with layers() (rows run along +x, successive rows along +z); beds go through bed().
import { layers, bed } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

const ORIGIN = [19, 6, 14];

export function build(g) {
  // the two beds: foot at x20, head at x19 against the west wall (facing west)
  bed(g, [20, 6, 14], "west", "red");
  bed(g, [20, 6, 20], "west", "red");

  // floor furnishing (y6): '.' stays as it is (air, or the bed halves already placed)
  // y6 rows, z14..z20 across x19..21
  layers(g, ORIGIN, {
    c: ["chest", { facing: "south" }],
    t: "spruce_fence",
    r: "brown_carpet",
    b: ["barrel", { facing: "up", open: "false" }],
  }, [
    [
      "..c", // z14: chest dresser against the north wall, beside the bed foot
      "...", // z15: lane
      ".t.", // z16: table post
      "rrr", // z17: rug
      "rrr", // z18: rug
      "...", // z19: lane
      "..b", // z20: barrel dresser beside the south bed's foot
    ],
  ]);

  // table top (top slab on the post, a table top at y8) and the standing lamp on it (y8 stands on the slab at y7)
  layers(g, [19, 7, 14], {
    s: ["spruce_slab", { type: "top" }],
    l: ["lantern", { hanging: "false" }],
  }, [
    ["...", "...", ".s.", "...", "...", "...", "..."],
  ]);
  layers(g, [19, 8, 14], {
    l: ["lantern", { hanging: "false" }],
  }, [
    ["...", "...", ".l.", "...", "...", "...", "..."],
  ]);
}
